"""Corrections of the 26 original dishes; no runtime recipe generation.

Cereals/lentils are dry, meat/fish are raw edible portions, chickpeas/beans
are boiled and drained. Product names identify ready-to-eat exceptions.
Nutrition is a reference estimate; retail costs and storage assumptions are
separate from nutrient verification.
"""
from .curated_recipes import entry


def base(name, ingredients, minutes, diet, allergens, steps, cost,
         slot="main", batch=False, side=""):
    recipe = entry(name, ingredients, minutes, diet, allergens, steps, slot)
    recipe.update(cost=cost, cost_status="unverified_planning_estimate", side_dish=side,
                  batch_servings=3 if batch else 1, storage_days=2 if batch else 0)
    return recipe


